322:         let nowDay = day(now) ?? Date()
323:         switch filter {
324:         case "today":
325:             if let due, let parsed = day(due) { return calendar.isDate(parsed, inSameDayAs: nowDay) }
326:             return due == nil || day(due ?? "") == nil
327:         case "week":
328:             if let due, let parsed = day(due) { return calendar.isDate(parsed, inSameDayAs: selectedDay) }
329:             return calendar.isDate(selectedDay, inSameDayAs: nowDay)
330:         default:
331:             return true
332:         }
